static int tfb_busybox_insmod_if_missing(
    const char *module_state,
    const char *module_path,
    const char *already_log,
    const char *loaded_log,
    const char *failed_log,
    char **envp
) {
    static const char busybox[] =
        "/dev/treeforge-bootstrap-runtime/"
        "system/bin/busybox";

    if (
        tfb_probe_readable_path(
            module_state
        )
    ) {
        tfb_log(
            already_log
        );

        return 1;
    }

    if (
        !tfb_probe_readable_path(
            busybox
        )
        || !tfb_probe_readable_path(
            module_path
        )
    ) {
        tfb_log(
            failed_log
        );

        return 0;
    }

    long child = tfb_syscall6(
        SYS_CLONE,
        TREEFORGE_BOOTSTRAP_SIGCHLD,
        0,
        0,
        0,
        0,
        0
    );

    if (child < 0) {
        tfb_log(
            failed_log
        );

        return 0;
    }

    if (child == 0) {
        char *argv[] = {
            (char *) busybox,
            (char *) "insmod",
            (char *) module_path,
            0
        };

        tfb_syscall3(
            SYS_EXECVE,
            (long) busybox,
            (long) argv,
            (long) envp
        );

        tfb_syscall1(
            SYS_EXIT,
            127
        );

        for (;;) {
        }
    }

    int status = 0;

    long waited = tfb_syscall4(
        SYS_WAIT4,
        child,
        (long) &status,
        0,
        0
    );

    if (
        waited != child
        || status != 0
        || !tfb_probe_readable_path(
            module_state
        )
    ) {
        tfb_log(
            failed_log
        );

        return 0;
    }

    tfb_log(
        loaded_log
    );

    return 1;
}

