        0,
        0,
        0,
        0
    );

    if (child < 0) {
        tfb_log(
            failed_log
        );

        return 0;
    }

    if (child == 0) {
        /*
         * Preserve the original flat-path contract. For versioned
         * vendor_dlkm layouts, resolve by basename under the running
         * kernel's module directory before invoking insmod.
         */
        static const char resolve_and_insert[] =
            "p=\"$1\"; "
            "if [ ! -r \"$p\" ]; then "
            "  base=${p##*/}; "
            "  root=/vendor_dlkm/lib/modules; "
            "  rel=$(\"$0\" uname -r); "
            "  if [ -d \"$root/$rel\" ]; then "
            "    p=$(\"$0\" find \"$root/$rel\" "
            "      -type f -name \"$base\" -print -quit); "
            "  else "
            "    p=$(\"$0\" find \"$root\" "
            "      -type f -name \"$base\" -print -quit); "
            "  fi; "
            "fi; "
            "if [ -z \"$p\" ] || [ ! -r \"$p\" ]; then "
            "  echo TFB_TOUCH_MODULE_PATH_MISSING >/dev/kmsg "
            "    2>/dev/null || true; "
            "  exit 43; "
            "fi; "
            "printf 'TFB_TOUCH_MODULE_PATH=%s\\n' \"$p\" "
            "  >/dev/kmsg 2>/dev/null || true; "
            "exec \"$0\" insmod \"$p\"";

        char *argv[] = {
            (char *) busybox,
            (char *) "sh",
            (char *) "-c",
            (char *) resolve_and_insert,
            (char *) busybox,
            (char *) module_path,
            0
        };

        tfb_syscall3(
            SYS_EXECVE,
            (long) busybox,
            (long) argv,
            (long) envp
        );

        tfb_syscall1(
            SYS_EXIT,
            127
        );

        for (;;) {
        }
    }

    int status = 0;

    long waited = tfb_syscall4(
        SYS_WAIT4,
        child,
        (long) &status,
        0,
        0
    );

    if (
        waited != child
        || status != 0
        || !tfb_probe_readable_path(
            module_state
        )
    ) {
        tfb_log(
            failed_log
        );

        return 0;
    }

    tfb_log(
        loaded_log
    );

    return 1;
}
